//////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//	-100 to -199 Command Errors
//	A command error indicates that the test set's GPIB parser has detected an IEEE 488.2 syntax error. 
//	When one of these errors is generated, the command error bit in the event status register is set.
//
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//Command errors
#define ERR_COMMAND_ERROR					-100		// <Command error> 未定义的语法错误
#define ERR_INVALID_CHARACTER				-101		// <Invalid character> 程序信息字符串中出现无效字符
#define	ERR_SYNTAX_ERROR					-102		// <Syntax error> 存在未被识别的命令或数据类型
#define ERR_INVALID_SEPARATOR				-103		// <Invalid separator> 要求为分隔符，但是发送了不是分割符的字符
#define ERR_DATA_TYPE_ERROR					-104		// <Data type error> 当前数据类型与所要求的类型不符
#define ERR_GET_NOT_ALLOWED					-105		// <GET not allowed> 在程序信息中收到群执行触发(GET)
#define ERR_SEMICOLON_UNWANTED				-106		// <Semicolon unwanted> 存在一个或几个多余的分号
