#define ERR_PARAMETER_NOT_ALLOWED			-108		// <Parameter not allowed> 参数的数量超出了命令要求的数量
#define ERR_MISSING_PARAMETER				-109		// <Missing parameter> 参数的数量少于命令要求的数量，或未输入参数
