#define ERR_NUMERIC_DATA_ERROR				-120		// <Numeric data error> 未定义的数值数据错误
#define ERR_INVALID_CHAR_IN_NUM				-121		// <Invalid character in number> 在数值数据中出现了不被当先命令所接受的数据字符
#define ERR_EXPONENT_TOO_LARGE				-123		// <Exponent too large> 指数的绝对值超过32000
#define ERR_TOO_MANY_DIGITS					-124		// <Too many digits> 十进制数据除开前置0后，数据的长度超过255个字符
#define ERR_NUMERIC_DATA_NOT_ALLOWED		-128		// <Numeric data not allowed> 在不接受数值数据元素的位置收到正确格式的数值数据元素
