#define ERR_BLOCK_DATA_NOT_ALLOWED			-168		// <Block data not allowed> 在此仪器不接受数据块元素的位置收到数据块元素
//Expression errors
#define ERR_EXPRESSION_ERROR				-170		// <Expression error> 未定义的表达式错误
#define ERR_INVALID_EXPRESSION				-171		// <Invalid expression> 表达式数据元素无效。例如，括号不成对或使用非法字符
#define ERR_EXPRESSION_DATA_NOT_ALLOWED		-178		// <Expression data not allowed> 在此仪器不接受表达式数据元素的位置收到表达式数据元素
//Macro errors
#define ERR_MACRO_ERROR						-180		// <Macro error> 未定义的宏错误
#define ERR_INVALID_OUTSIDE_MACRO_DEFINE	-181		// <Invalid outside macro definition> 在宏定义之外遇到宏参数占位符“$”
#define ERR_INVALID_INSIDE_MACRO_DEFINE		-183		// <Invalid inside macro definition> 宏定义时(*DDT,*DMC)，宏的内容语法错误
#define ERR_MACRO_PARAMETER_ERROR			-184		// <Macro parameter error> 宏定义内的命令有错误的参数个数或参数类型

